{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "metric", "sql": "SELECT service_name, metric, min(value) mn, max(value) mx, count(*) n FROM abnormal_metrics WHERE metric='k8s.deployment.available' AND service_name IN ('profile','search') GROUP BY 1,2", "claim": "search deployment has 0 available replicas across the entire abnormal window (17 samples, all 0)."},
        {"kind": "metric", "sql": "SELECT attr_k8s_pod_name pod, time, value FROM abnormal_metrics WHERE metric='k8s.container.restarts' AND attr_k8s_pod_name LIKE 'search%' ORDER BY 2", "claim": "search pod restart counter climbs from 6 to 8 during the abnormal window, and its CPU metrics stop."},
        {"kind": "trace", "sql": "SELECT span_name, attr_span_kind, count(*) n FROM abnormal_traces WHERE service_name='search' GROUP BY 1,2", "claim": "search emits almost no spans in the abnormal window (3 spans, versus about 2,600 in normal)."},
        {"kind": "trace", "sql": "SELECT 'norm' p, count(*) n FROM normal_traces WHERE span_name = 'search.Search/Nearby' UNION ALL SELECT 'abn', count(*) FROM abnormal_traces WHERE span_name = 'search.Search/Nearby'", "claim": "frontend's search.Search/Nearby calls fall from 1746 in normal to 1120 in abnormal, with almost none completing on the search side."}
      ]
    },
    {
      "service": "profile",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "metric", "sql": "SELECT service_name, metric, min(value) mn, max(value) mx, count(*) n FROM abnormal_metrics WHERE metric='k8s.deployment.available' AND service_name IN ('profile','search') GROUP BY 1,2", "claim": "profile deployment has 0 available replicas across the entire abnormal window (18 samples, all 0)."},
        {"kind": "metric", "sql": "SELECT attr_k8s_pod_name pod, time, value FROM abnormal_metrics WHERE metric='k8s.container.restarts' AND attr_k8s_pod_name LIKE 'profile%' ORDER BY 2", "claim": "profile pod restart counter rises from 6 to 8 during the abnormal window, with no CPU metrics after the failure."},
        {"kind": "trace", "sql": "SELECT 'norm' p, count(*) n FROM normal_traces WHERE span_name LIKE 'profile.Profile/%' UNION ALL SELECT 'abn', count(*) FROM abnormal_traces WHERE span_name LIKE 'profile.Profile/%'", "claim": "profile.Profile/GetProfiles calls drop from 2954 in normal to 666 in abnormal, and no profile-service server spans remain."},
        {"kind": "log", "sql": "SELECT service_name, level, message, count(*) c FROM abnormal_logs WHERE level='ERROR' GROUP BY 1,2,3 ORDER BY c DESC", "claim": "frontend logs 'Get profiles failed' 443 times in the abnormal window, showing profile calls failing."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {"kind": "trace", "sql": "SELECT span_name, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='frontend' AND attr_span_kind='Server' AND span_name='HTTP /hotels' GROUP BY 1", "claim": "frontend HTTP /hotels (the search path) server spans: 1119 in abnormal, 1113 with Error status, versus 0 errors in normal."}
      ]
    },
    {
      "from": "profile",
      "to": "frontend",
      "evidence": [
        {"kind": "trace", "sql": "SELECT span_name, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='frontend' AND attr_span_kind='Server' AND span_name='HTTP /recommendations' GROUP BY 1", "claim": "frontend HTTP /recommendations server spans: 659 in abnormal, 656 with Error status, versus 0 errors in normal."}
      ]
    }
  ]
}
